/**
 * 触触搜 popup.bundle.js (auto-generated by scripts/bundle-shared-deps.mjs)
 * Concat of (in order):
 *   - shared/logger.js
 *   - shared/runtimeClient.js
 *   - shared/storageDefaults.js
 *   - shared/keywordClient.js
 *   - popup/popup.js
 * Do not edit. Source files unchanged; this is build-time only.
 */

/* ============================================================
 * BEGIN shared/logger.js
 * ============================================================ */
(function () {
  'use strict';

  const TRACE_KEY = 'ccs_trace_buffer';
  const TRACE_LIMIT = 200;
  const EXTENSION_LABEL = 'extension';
  const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };

  let debugEnabled = false;
  let debugLoaded = false;

  function getChrome() {
    try { return globalThis.chrome || null; } catch (_) { return null; }
  }

  function createRequestId(prefix = 'req') {
    const rand = Math.random().toString(36).slice(2, 8);
    return `${prefix}-${Date.now().toString(36)}-${rand}`;
  }

  function normalizeLevel(level) {
    return Object.prototype.hasOwnProperty.call(LEVELS, level) ? level : 'info';
  }

  function shouldWriteConsole(level) {
    if (debugEnabled) return true;
    return level === 'warn' || level === 'error';
  }

  function format(module, phase, requestId, message) {
    return `[${EXTENSION_LABEL}][${module || 'app'}][${phase || 'log'}][${requestId || '-'}] ${message || ''}`;
  }

  function writeTrace(record) {
    const ch = getChrome();
    const storage = ch?.storage?.session || ch?.storage?.local;
    if (!storage?.get || !storage?.set) return;

    try {
      storage.get([TRACE_KEY], (data) => {
        const current = Array.isArray(data?.[TRACE_KEY]) ? data[TRACE_KEY] : [];
        current.push(record);
        const next = current.slice(-TRACE_LIMIT);
        storage.set({ [TRACE_KEY]: next }, () => {
          // Best effort only. Do not log recursively from the logger.
          try { void ch.runtime?.lastError; } catch (_) { /* noop */ }
        });
      });
    } catch (_) {
      // Best effort only.
    }
  }

  function log(level, module, phase, requestId, message, data) {
    const normalized = normalizeLevel(level);
    const record = {
      ts: Date.now(),
      level: normalized,
      module: module || 'app',
      phase: phase || 'log',
      requestId: requestId || '',
      message: message || '',
      data: typeof data === 'undefined' ? null : data
    };

    const line = format(record.module, record.phase, record.requestId, record.message);
    if (shouldWriteConsole(normalized)) {
      const method = normalized === 'error' ? 'error' : normalized === 'warn' ? 'warn' : 'log';
      try {
        if (typeof data === 'undefined') console[method](line);
        else console[method](line, data);
      } catch (_) {
        // Console can be unavailable in some extension contexts.
      }
    }

    if (debugEnabled || normalized !== 'debug') {
      writeTrace(record);
    }
  }

  function setDebug(enabled) {
    debugEnabled = !!enabled;
    debugLoaded = true;
  }

  function init() {
    if (debugLoaded) return;
    const ch = getChrome();
    try {
      ch?.storage?.local?.get?.(['ccs_debug'], (data) => {
        setDebug(!!data?.ccs_debug);
      });
      ch?.storage?.onChanged?.addListener?.((changes, areaName) => {
        if (areaName !== 'local' || !changes.ccs_debug) return;
        setDebug(!!changes.ccs_debug.newValue);
      });
    } catch (_) {
      setDebug(false);
    }
  }

  function getTraceBuffer() {
    const ch = getChrome();
    const storage = ch?.storage?.session || ch?.storage?.local;
    return new Promise((resolve) => {
      if (!storage?.get) { resolve([]); return; }
      try {
        storage.get([TRACE_KEY], (data) => {
          resolve(Array.isArray(data?.[TRACE_KEY]) ? data[TRACE_KEY] : []);
        });
      } catch (_) {
        resolve([]);
      }
    });
  }

  function clearTraceBuffer() {
    const ch = getChrome();
    const storage = ch?.storage?.session || ch?.storage?.local;
    return new Promise((resolve) => {
      if (!storage?.remove) { resolve(); return; }
      try { storage.remove([TRACE_KEY], () => resolve()); } catch (_) { resolve(); }
    });
  }

  const api = {
    createRequestId,
    format,
    init,
    setDebug,
    getTraceBuffer,
    clearTraceBuffer,
    debug: (module, phase, requestId, message, data) => log('debug', module, phase, requestId, message, data),
    info: (module, phase, requestId, message, data) => log('info', module, phase, requestId, message, data),
    warn: (module, phase, requestId, message, data) => log('warn', module, phase, requestId, message, data),
    error: (module, phase, requestId, message, data) => log('error', module, phase, requestId, message, data)
  };

  globalThis.CCSLogger = api;
  api.init();
})();
/* ============================================================
 * END shared/logger.js
 * ============================================================ */

/* ============================================================
 * BEGIN shared/runtimeClient.js
 * ============================================================ */
(function () {
  'use strict';

  const DEFAULT_RUNTIME_TIMEOUT_MS = 1500;
  const DEFAULT_TAB_TIMEOUT_MS = 900;
  const CONTENT_BOOT_DELAY_MS = 100;

  const ErrorCodes = {
    TIMEOUT: 'TIMEOUT',
    RUNTIME_UNAVAILABLE: 'RUNTIME_UNAVAILABLE',
    SW_UNAVAILABLE: 'SW_UNAVAILABLE',
    CONTENT_UNAVAILABLE: 'CONTENT_UNAVAILABLE',
    PERMISSION_DENIED: 'PERMISSION_DENIED',
    SEND_FAILED: 'SEND_FAILED'
  };

  function logger() {
    return globalThis.CCSLogger || {
      createRequestId: (prefix) => `${prefix || 'req'}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      debug: () => {},
      info: () => {},
      warn: () => {},
      error: () => {}
    };
  }

  function getChrome() {
    try { return globalThis.chrome || null; } catch (_) { return null; }
  }

  function elapsed(startedAt) {
    return Date.now() - startedAt;
  }

  function makeError(code, message, cause) {
    return {
      code,
      message: message || code,
      cause: cause ? String(cause) : undefined
    };
  }

  function normalizeResponse(response, requestId, startedAt) {
    if (response && typeof response === 'object' && response.ok === false) {
      return {
        ...response,
        requestId: response.requestId || requestId,
        elapsedMs: response.elapsedMs ?? elapsed(startedAt)
      };
    }
    if (response && typeof response === 'object' && response.ok === true && Object.prototype.hasOwnProperty.call(response, 'data')) {
      return {
        ...response,
        requestId: response.requestId || requestId,
        elapsedMs: response.elapsedMs ?? elapsed(startedAt)
      };
    }
    return {
      ok: true,
      data: response,
      requestId,
      elapsedMs: elapsed(startedAt)
    };
  }

  function isReceivingEndError(message) {
    return /Receiving end does not exist|Could not establish connection|message port closed|Extension context invalidated/i.test(message || '');
  }

  function isPermissionError(message) {
    return /Cannot access|The extensions gallery cannot be scripted|chrome:\/\/|Cannot access contents of url|permission/i.test(message || '');
  }

  function delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  function sendRuntimeMessage(message, options = {}) {
    const ch = getChrome();
    const log = logger();
    const action = message?.action || message?.type || 'runtime-message';
    const requestId = options.requestId || message?.requestId || log.createRequestId(action);
    const timeoutMs = Number.isFinite(options.timeoutMs) ? options.timeoutMs : DEFAULT_RUNTIME_TIMEOUT_MS;
    const retries = Number.isFinite(options.retries) ? options.retries : 0;
    const startedAt = Date.now();

    if (!ch?.runtime?.sendMessage) {
      return Promise.resolve({
        ok: false,
        error: makeError(ErrorCodes.RUNTIME_UNAVAILABLE, 'chrome.runtime.sendMessage unavailable'),
        requestId,
        elapsedMs: elapsed(startedAt)
      });
    }

    const payload = { ...(message || {}), requestId };

    function attempt(remainingRetries) {
      log.debug('runtime', 'send', requestId, action, { timeoutMs, remainingRetries });
      return new Promise((resolve) => {
        let settled = false;
        const timer = setTimeout(() => {
          if (settled) return;
          settled = true;
          log.warn('runtime', 'timeout', requestId, action, { timeoutMs });
          resolve({
            ok: false,
            error: makeError(ErrorCodes.TIMEOUT, `${action} timed out after ${timeoutMs}ms`),
            requestId,
            elapsedMs: elapsed(startedAt)
          });
        }, timeoutMs);

        try {
          ch.runtime.sendMessage(payload, (response) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);

            const lastError = ch.runtime.lastError?.message || '';
            if (lastError) {
              const code = isReceivingEndError(lastError) ? ErrorCodes.SW_UNAVAILABLE : ErrorCodes.SEND_FAILED;
              log.warn('runtime', 'lastError', requestId, action, { code, message: lastError });
              resolve({
                ok: false,
                error: makeError(code, lastError),
                requestId,
                elapsedMs: elapsed(startedAt)
              });
              return;
            }

            const normalized = normalizeResponse(response, requestId, startedAt);
            log.debug('runtime', normalized.ok ? 'response' : 'error', requestId, action, normalized.ok ? undefined : normalized.error);
            resolve(normalized);
          });
        } catch (error) {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          log.warn('runtime', 'exception', requestId, action, { message: error?.message || String(error) });
          resolve({
            ok: false,
            error: makeError(ErrorCodes.SEND_FAILED, error?.message || String(error)),
            requestId,
            elapsedMs: elapsed(startedAt)
          });
        }
      }).then(async (result) => {
        if (result.ok || remainingRetries <= 0) return result;
        if (![ErrorCodes.TIMEOUT, ErrorCodes.SW_UNAVAILABLE].includes(result.error?.code)) return result;
        await delay(options.retryDelayMs || 120);
        return attempt(remainingRetries - 1);
      });
    }

    return attempt(retries);
  }

  async function executeContentScript(tabId, files) {
    const ch = getChrome();
    if (tabId == null || !ch?.scripting?.executeScript) return false;
    try {
      await ch.scripting.executeScript({
        target: { tabId },
        files: files || ['content.js']
      });
      return true;
    } catch (_) {
      return false;
    }
  }

  function sendTabMessage(tabId, message, options = {}) {
    const ch = getChrome();
    const log = logger();
    const action = message?.action || message?.type || 'tab-message';
    const requestId = options.requestId || message?.requestId || log.createRequestId(action);
    const timeoutMs = Number.isFinite(options.timeoutMs) ? options.timeoutMs : DEFAULT_TAB_TIMEOUT_MS;
    const injectFallback = options.injectFallback !== false;
    const startedAt = Date.now();

    if (tabId == null || !ch?.tabs?.sendMessage) {
      return Promise.resolve({
        ok: false,
        error: makeError(ErrorCodes.CONTENT_UNAVAILABLE, 'tabId or chrome.tabs.sendMessage unavailable'),
        requestId,
        elapsedMs: elapsed(startedAt)
      });
    }

    const payload = { ...(message || {}), requestId };

    function attempt(allowInject) {
      log.debug('tab', 'send', requestId, action, { tabId, timeoutMs, allowInject });
      return new Promise((resolve) => {
        let settled = false;
        const timer = setTimeout(() => {
          if (settled) return;
          settled = true;
          log.warn('tab', 'timeout', requestId, action, { tabId, timeoutMs });
          resolve({
            ok: false,
            error: makeError(ErrorCodes.TIMEOUT, `${action} timed out after ${timeoutMs}ms`),
            requestId,
            elapsedMs: elapsed(startedAt)
          });
        }, timeoutMs);

        try {
          ch.tabs.sendMessage(tabId, payload, (response) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);

            const lastError = ch.runtime?.lastError?.message || '';
            if (lastError) {
              const code = isPermissionError(lastError)
                ? ErrorCodes.PERMISSION_DENIED
                : ErrorCodes.CONTENT_UNAVAILABLE;
              log.warn('tab', 'lastError', requestId, action, { tabId, code, message: lastError });
              resolve({
                ok: false,
                error: makeError(code, lastError),
                requestId,
                elapsedMs: elapsed(startedAt)
              });
              return;
            }

            resolve(normalizeResponse(response, requestId, startedAt));
          });
        } catch (error) {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({
            ok: false,
            error: makeError(ErrorCodes.SEND_FAILED, error?.message || String(error)),
            requestId,
            elapsedMs: elapsed(startedAt)
          });
        }
      }).then(async (result) => {
        if (result.ok || !allowInject || !injectFallback) return result;
        const messageText = result.error?.message || '';
        if (result.error?.code !== ErrorCodes.CONTENT_UNAVAILABLE && !isReceivingEndError(messageText)) return result;
        const injected = await executeContentScript(tabId, options.injectFiles || ['content.js']);
        if (!injected) return result;
        await delay(options.injectDelayMs || CONTENT_BOOT_DELAY_MS);
        return attempt(false);
      });
    }

    return attempt(true);
  }

  globalThis.CCSRuntimeClient = {
    ErrorCodes,
    sendRuntimeMessage,
    sendTabMessage,
    executeContentScript
  };
})();
/* ============================================================
 * END shared/runtimeClient.js
 * ============================================================ */

/* ============================================================
 * BEGIN shared/storageDefaults.js
 * ============================================================ */
(function () {
  'use strict';

  const DEFAULT_SETTINGS = {
    mode: 'normal',
    theme: 'default',
    opacity: 1,
    position: null,
    layout: 'float',
    globalDock: false,
    barClosed: false,
    blacklist: [],
    isBlacklisted: false,
    miniButtons: ['baidu', 'google', 'chuchusou', 'copy', 'lowercase'],
    shortcutKey: 'Alt+S'
  };

  const DEFAULTS = {
    enabled: true,
    ccs_debug: false,
    ccs_voice_enabled: false,
    ccs_schema_version: 1,
    ccs_settings: DEFAULT_SETTINGS
  };

  function getChrome() {
    try { return globalThis.chrome || null; } catch (_) { return null; }
  }

  function log(level, phase, requestId, message, data) {
    const logger = globalThis.CCSLogger;
    if (logger?.[level]) logger[level]('storage', phase, requestId, message, data);
  }

  function ensureDefaults(options = {}) {
    const ch = getChrome();
    const requestId = options.requestId || globalThis.CCSLogger?.createRequestId?.('storage-defaults') || `storage-${Date.now()}`;
    const source = options.source || 'unknown';

    return new Promise((resolve) => {
      const local = ch?.storage?.local;
      if (!local?.get || !local?.set) {
        resolve({ ok: false, patched: [], error: 'storage-unavailable', requestId });
        return;
      }

      const keys = Object.keys(DEFAULTS);
      log('debug', 'defaults-start', requestId, 'checking defaults', { source, keys });
      try {
        local.get(keys, (current) => {
          const lastError = ch.runtime?.lastError?.message || '';
          if (lastError) {
            log('warn', 'defaults-read-error', requestId, lastError, { source });
            resolve({ ok: false, patched: [], error: lastError, requestId });
            return;
          }

          const patch = {};
          keys.forEach((key) => {
            if (typeof current?.[key] === 'undefined') patch[key] = DEFAULTS[key];
          });

          if (Object.keys(patch).length === 0) {
            resolve({ ok: true, patched: [], requestId });
            return;
          }

          local.set(patch, () => {
            const writeError = ch.runtime?.lastError?.message || '';
            if (writeError) {
              log('warn', 'defaults-write-error', requestId, writeError, { source, patch: Object.keys(patch) });
              resolve({ ok: false, patched: Object.keys(patch), error: writeError, requestId });
              return;
            }
            log('info', 'defaults-written', requestId, 'storage defaults patched', { source, keys: Object.keys(patch) });
            resolve({ ok: true, patched: Object.keys(patch), requestId });
          });
        });
      } catch (error) {
        const message = error?.message || String(error);
        log('warn', 'defaults-exception', requestId, message, { source });
        resolve({ ok: false, patched: [], error: message, requestId });
      }
    });
  }

  globalThis.CCSStorageDefaults = {
    DEFAULTS,
    DEFAULT_SETTINGS,
    ensureDefaults
  };
})();
/* ============================================================
 * END shared/storageDefaults.js
 * ============================================================ */

/* ============================================================
 * BEGIN shared/keywordClient.js
 * ============================================================ */
/**
 * CCSKeywordClient —— popup / sidepanel 共用的关键字获取客户端（C 档重构产物）
 *
 * 这是 background/KeywordService.js 的客户端镜像：popup 和 sidepanel 不直接 send
 * message，统一过这层薄客户端，让两边的行为保证一致（getCurrentKeyword 不再各写一份）。
 *
 * 暴露：
 * - CCSKeywordClient.requestKeyword(intent, options)  —— 主入口
 * - CCSKeywordClient.readInstantCache(tabId)  —— popup 用，从 storage 读上次的缓存先渲染
 * - CCSKeywordClient.getActiveTab()  —— 工具，查当前 tab
 * - CCSKeywordClient.INTENTS  —— intent 字面量（避免拼写错误）
 *
 * 使用方式：
 *   const fresh = await CCSKeywordClient.requestKeyword('popup-open');
 *   // 或 popup 推荐的瞬时模式：
 *   const fresh = await CCSKeywordClient.requestKeyword('popup-open', {
 *     instantFromStorage: true,
 *     onInstant: (cached) => { this.keyword = cached; this.renderKeyword(); }
 *   });
 */
(function () {
  'use strict';

  const INTENTS = {
    POPUP_OPEN: 'popup-open',
    SIDEPANEL_INIT: 'sidepanel-init',
    SIDEPANEL_REFRESH: 'sidepanel-refresh'
  };

  const STORAGE_PREFIX = 'ccs_kw_';
  const STORAGE_TTL_MS = 5 * 60 * 1000; // 必须和 background/KeywordService.js 的 KEYWORD_STORAGE_TTL_MS 一致
  const REQUEST_TIMEOUT_MS = 1500;

  // 三段兜底拿 active tab：
  // 1) currentWindow:true（popup 上下文稳，sidepanel 偶发返回空数组）
  // 2) chrome.windows.getCurrent() 拿到 windowId 后显式 query({windowId})
  // 3) lastFocusedWindow:true（多窗口/失焦场景兜底）
  // 任一步成功立刻返回，避免假装拿到 {id:null,url:'',title:''} 占位对象。
  async function getActiveTab() {
    const fromCurrent = await new Promise((resolve) => {
      try {
        chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
          resolve(tabs && tabs[0] ? tabs[0] : null);
        });
      } catch (_) { resolve(null); }
    });
    if (fromCurrent) return fromCurrent;

    try {
      const win = await new Promise((resolve) => {
        try { chrome.windows.getCurrent((w) => resolve(w || null)); } catch (_) { resolve(null); }
      });
      if (win?.id != null) {
        const fromWindow = await new Promise((resolve) => {
          try {
            chrome.tabs.query({ active: true, windowId: win.id }, (tabs) => {
              resolve(tabs && tabs[0] ? tabs[0] : null);
            });
          } catch (_) { resolve(null); }
        });
        if (fromWindow) return fromWindow;
      }
    } catch (_) { /* ignore */ }

    return new Promise((resolve) => {
      try {
        chrome.tabs.query({ active: true, lastFocusedWindow: true }, (tabs) => {
          resolve(tabs && tabs[0] ? tabs[0] : null);
        });
      } catch (_) { resolve(null); }
    });
  }

  /**
   * 直接读 storage 缓存（不发消息，避免唤醒 SW）。
   * popup 打开时用于"零等待"先渲染上次的关键字。
   *
   * 强校验 URL：缓存的 url 不等于当前 url 就丢弃，避免在 chrome:// 等无法取
   * selection 的页面把上一个页面的关键字"假装"成本页的（用户会误以为正常获取）。
   *
   * @param {number} tabId
   * @param {string} [currentUrl]  —— 当前 tab 的 URL；不传则跳过 URL 校验
   */
  async function readInstantCache(tabId, currentUrl) {
    if (tabId == null || !chrome?.storage?.local) return null;
    return new Promise((resolve) => {
      const key = `${STORAGE_PREFIX}${tabId}`;
      try {
        chrome.storage.local.get([key], (data) => {
          if (chrome.runtime.lastError) { resolve(null); return; }
          const entry = data?.[key];
          if (!entry || typeof entry !== 'object') { resolve(null); return; }
          if (Date.now() - (entry.ts || 0) > STORAGE_TTL_MS) { resolve(null); return; }
          // URL 强校验：缓存 URL ≠ 当前 URL → stale → 丢弃
          if (currentUrl && entry.url && entry.url !== currentUrl) {
            resolve(null);
            return;
          }
          resolve({ text: entry.text || '', raw: entry.raw || entry.text || '' });
        });
      } catch (_) { resolve(null); }
    });
  }

  /**
   * 请求关键字。intent 决定 background 的策略。
   *
   * @param {string} intent  —— 见 INTENTS
   * @param {Object} [options]
   * @param {Object} [options.tab]  —— 已知的 tab 对象（省去查 active tab 的 round-trip）
   * @param {boolean} [options.instantFromStorage]  —— 先并发读 storage 缓存，命中即触发 onInstant
   * @param {Function} [options.onInstant]  —— 当 storage 命中且尚未拿到新鲜值时回调（用于先渲染 UI）
   * @returns {Promise<{text: string, raw: string}>}  —— 新鲜值（覆盖任何 instant 值）
   */
  async function requestKeyword(intent, options = {}) {
    const { tab = null, instantFromStorage = false, onInstant = null } = options;
    const activeTab = tab || await getActiveTab();
    if (!activeTab) return { text: '', raw: '' };

    let freshResolved = false;
    let onInstantCalled = false;

    // 并发：读 storage（快）+ 发消息拿新鲜（慢）
    if (instantFromStorage && typeof onInstant === 'function') {
      readInstantCache(activeTab.id, activeTab.url).then((cached) => {
        // 只有"新鲜值还没回来 + 缓存命中 + 用户没主动取消"才回调 instant
        if (!freshResolved && !onInstantCalled && cached && cached.text) {
          onInstantCalled = true;
          try { onInstant(cached); } catch (e) {
            console.warn('[触触搜][KeywordClient] onInstant 回调异常:', e);
          }
        }
      });
    }

    const request = {
      action: 'getKeyword',
      tabId: activeTab.id,
      url: activeTab.url,
      title: activeTab.title,
      intent
    };

    try {
      const client = globalThis.CCSRuntimeClient;
      if (client?.sendRuntimeMessage) {
        const result = await client.sendRuntimeMessage(request, {
          timeoutMs: options.timeoutMs || REQUEST_TIMEOUT_MS,
          retries: options.retries ?? 1
        });
        freshResolved = true;
        if (!result.ok) {
          globalThis.CCSLogger?.warn?.('keyword', 'request-failed', result.requestId, result.error?.code || 'KEYWORD_FAILED', result.error);
          return { text: '', raw: '' };
        }
        const response = result.data || {};
        return {
          text: response?.text || '',
          raw: response?.raw || response?.text || ''
        };
      }

      return await new Promise((resolve) => {
        try {
          chrome.runtime.sendMessage(request, (response) => {
            freshResolved = true;
            if (chrome.runtime.lastError) {
              resolve({ text: '', raw: '' });
              return;
            }
            resolve({
              text: response?.text || '',
              raw: response?.raw || response?.text || ''
            });
          });
        } catch (e) {
          freshResolved = true;
          console.warn('[触触搜][KeywordClient] sendMessage 异常:', e);
          resolve({ text: '', raw: '' });
        }
      });
    } catch (e) {
      freshResolved = true;
      console.warn('[触触搜][KeywordClient] requestKeyword 异常:', e);
      return { text: '', raw: '' };
    }
  }

  globalThis.CCSKeywordClient = {
    requestKeyword,
    readInstantCache,
    getActiveTab,
    INTENTS
  };
})();
/* ============================================================
 * END shared/keywordClient.js
 * ============================================================ */

/* ============================================================
 * BEGIN popup/popup.js
 * ============================================================ */
/**
 * 触触搜 Popup —— 极简渲染模式（参考 test_plasmo_demo）
 *
 * v1.6.19 设计原则：
 * - 菜单是静态 HTML（编译期由 scripts/prebuild-popup-menu.mjs 注入完整结构）
 * - popup.js 只做：绑事件、读关键字 storage、处理 pinned cover、设置面板
 * - 0 fetch 拉菜单 / 0 sendMessage 醒 SW / 0 DOM 构建
 * - 商店生产 popup 首屏 = HTML 解析时间（~10-20ms）
 *
 * dev mode（plasmo dev 没跑 prebuild）：popup.html 自带 6 个常用菜单作 fallback
 * —— 完整菜单看 build/ 产物，dev 用最常用功能。
 */

// ============================================================================
// v1.6.22 诊断录像（IIFE 在 popup.js 顶层即刻执行）
// ============================================================================
// 设计：popup.js 一被解析就启动"录像"，比 class 实例化 / init() 还早。
// 哪怕 init() 整个卡 3 秒，期间的 long tasks / console errors 都进了 buffer。
// 用户点 ⚙️ → 🩺 一键诊断时只是把已有 buffer 格式化复制走。
(function setupDiagRecording() {
  performance.mark('ccs-diag-script-start');

  const buffer = {
    scriptStartTs: Date.now(),
    scriptStartPerf: performance.now(),
    longTasks: [],
    errors: [],
    swPings: [], // 填充：{ sentAt, swNow, rttMs, error? }
    paints: [],  // first-paint / first-contentful-paint
    readyStateTimeline: [],  // 记录每次 document.readyState 变化的时间
    eventTimeline: []  // DOMContentLoaded / load 等事件触发时间
  };

  // 立即采样 readyState（IIFE 跑的时候 readyState 是什么）
  buffer.readyStateTimeline.push({
    state: document.readyState,
    perf: performance.now()
  });

  // 长任务监听：>50ms 主线程阻塞全部录进来
  try {
    if (typeof PerformanceObserver !== 'undefined') {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (buffer.longTasks.length < 100) {
            buffer.longTasks.push({
              name: entry.name,
              startTime: entry.startTime,
              duration: entry.duration
            });
          }
        }
      });
      observer.observe({ type: 'longtask', buffered: true });
      buffer._longTaskObserver = observer;

      // Paint timing —— first-paint / first-contentful-paint
      try {
        const paintObs = new PerformanceObserver((list) => {
          for (const e of list.getEntries()) {
            buffer.paints.push({ name: e.name, startTime: e.startTime });
          }
        });
        paintObs.observe({ type: 'paint', buffered: true });
      } catch (_) { /* paint timing 部分浏览器不支持 */ }
    }
  } catch (e) {
    buffer.errors.push({ ts: Date.now(), type: 'longtask-observer-init', msg: String(e?.message || e) });
  }

  // 记录 readystatechange / DOMContentLoaded / load 三大里程碑
  document.addEventListener('readystatechange', () => {
    buffer.readyStateTimeline.push({
      state: document.readyState,
      perf: performance.now()
    });
  });
  document.addEventListener('DOMContentLoaded', () => {
    buffer.eventTimeline.push({ name: 'DOMContentLoaded', perf: performance.now() });
  });
  window.addEventListener('load', () => {
    buffer.eventTimeline.push({ name: 'window.load', perf: performance.now() });
  });

  // console.error / console.warn 环形缓冲（最近 50 条）
  const wrapConsole = (level) => {
    const orig = console[level];
    console[level] = function (...args) {
      try {
        const msg = args.map((a) => {
          if (a instanceof Error) return `${a.name}: ${a.message}\n${a.stack || ''}`;
          if (typeof a === 'object') {
            try { return JSON.stringify(a); } catch (_) { return String(a); }
          }
          return String(a);
        }).join(' ');
        if (buffer.errors.length >= 50) buffer.errors.shift();
        buffer.errors.push({
          ts: Date.now(),
          perf: performance.now(),
          level,
          msg: msg.slice(0, 500) // 单条上限
        });
      } catch (_) { /* ignore wrap errors */ }
      return orig.apply(console, args);
    };
  };
  wrapConsole('error');
  wrapConsole('warn');

  // window 级错误
  window.addEventListener('error', (e) => {
    if (buffer.errors.length >= 50) buffer.errors.shift();
    buffer.errors.push({
      ts: Date.now(),
      perf: performance.now(),
      level: 'window-error',
      msg: `${e.message} @ ${e.filename}:${e.lineno}:${e.colno}`
    });
  });
  window.addEventListener('unhandledrejection', (e) => {
    if (buffer.errors.length >= 50) buffer.errors.shift();
    buffer.errors.push({
      ts: Date.now(),
      perf: performance.now(),
      level: 'unhandled-rejection',
      msg: String(e.reason?.stack || e.reason?.message || e.reason)
    });
  });

  // 暴露给 PopupMenuRenderer.copyDiagnosticReport() 用
  globalThis.__CCS_DIAG_BUFFER__ = buffer;
})();

class PopupMenuRenderer {
  constructor() {
    this.keyword = { text: '', raw: '' };
    this.currentMode = 'menu'; // 'menu' or 'settings'
    this.promptLibraryManager = null;
    this._settingsInitDone = false;
    this._promptLibraryLoadPromise = null;
  }

  async init() {
    performance.mark('ccs-popup-start');
    const initRequestId = globalThis.CCSLogger?.createRequestId?.('popup-init') || `popup-init-${Date.now()}`;
    globalThis.CCSLogger?.info?.('popup', 'init-start', initRequestId, 'popup init started');
    try {
      void globalThis.CCSStorageDefaults?.ensureDefaults?.({ source: 'popup', requestId: initRequestId });
      this.loadVersion();
      this.bindEvents();
      this.startKeywordLoad();
      // v1.6.22：initPinnedCover 推迟到 idle —— 内部串了 storage.get + fetch(coverPrompts.json)
      // + DOM render + 事件绑定。popupPin 默认 hidden=true，init 完才 hidden=false，
      // 不影响首屏菜单 + 关键字徽章可见。
      const idleSchedule = (fn) => {
        const ric = globalThis.requestIdleCallback;
        if (typeof ric === 'function') ric(fn, { timeout: 1200 });
        else setTimeout(fn, 200);
      };
      idleSchedule(() => { this.initPinnedCover(); });
      this._renderKeyword();
      performance.mark('ccs-popup-rendered');
      try {
        performance.measure('ccs-popup-ttfb', 'ccs-popup-start', 'ccs-popup-rendered');
        const m = performance.getEntriesByName('ccs-popup-ttfb')[0];
        if (m) console.log(`[触触搜][PERF] popup TTFB: ${m.duration.toFixed(1)}ms`);
      } catch (_) { /* perf 失败无所谓 */ }
      globalThis.CCSLogger?.info?.('popup', 'first-paint', initRequestId, 'popup first paint complete');
    } catch (error) {
      globalThis.CCSLogger?.error?.('popup', 'init-error', initRequestId, error?.message || String(error), { stack: error?.stack });
      console.error('[触触搜] Popup 初始化失败:', error);
      this.showError('加载失败，请重试');
    }
  }

  loadVersion() {
    const manifest = chrome.runtime.getManifest();
    const versionEl = document.getElementById('versionNumber');
    if (versionEl && manifest.version) {
      versionEl.textContent = `v${manifest.version}`;
    }
  }

  fetchJSON(path) {
    return fetch(chrome.runtime.getURL(path))
      .then((r) => r.ok ? r.json() : null)
      .catch(() => null);
  }

  startKeywordLoad() {
    // v1.6.19：popup 首屏不发 sendMessage('getKeyword') —— 商店生产环境 SW 30s
    // idle 即被回收，发消息会触发 SW 冷启动（importScripts 17 个 legacy + side
    // effects ~500ms-2s），跟 popup 渲染抢 CPU 导致 "卡住打不开"。
    // 改成：只读 storage 缓存（SW 写入选区时已经持久化）+ 监听 onChanged 实时刷
    // 新值。用户点击菜单时 handleClick 会兜底发消息（用户已感知 popup 开了）。
    this._keywordLoadPromise = (async () => {
      try {
        const tab = await CCSKeywordClient.getActiveTab();
        if (!tab?.id) return;
        this._activeTabId = tab.id;
        this._activeTabUrl = tab.url || '';
        const cached = await CCSKeywordClient.readInstantCache(tab.id, tab.url);
        if (cached?.text) {
          this.applyKeyword(cached);
        }
        // SW 后续写入 ccs_kw_<tabId>（例如内容脚本上报新选区）→ 自动刷新徽章
        const storageKey = `ccs_kw_${tab.id}`;
        this._kwStorageListener = (changes, areaName) => {
          if (areaName !== 'local') return;
          const change = changes[storageKey];
          if (!change?.newValue) return;
          if (change.newValue.url && this._activeTabUrl && change.newValue.url !== this._activeTabUrl) return;
          this.applyKeyword({
            text: change.newValue.text || '',
            raw: change.newValue.raw || change.newValue.text || ''
          });
        };
        try { chrome.storage.onChanged.addListener(this._kwStorageListener); } catch (_) { /* ignore */ }

        // Cache miss is common after first install/new tab. Keep first paint free of
        // SW work, then refresh the badge in the background with a bounded request.
        const scheduleFreshKeyword = (fn) => {
          const ric = globalThis.requestIdleCallback;
          if (typeof ric === 'function') ric(fn, { timeout: cached?.text ? 500 : 1200 });
          else setTimeout(fn, cached?.text ? 250 : 900);
        };
        scheduleFreshKeyword(() => {
          this.refreshKeyword({
            timeoutMs: cached?.text ? 900 : 1200,
            retries: 0
          }).catch((error) => {
            globalThis.CCSLogger?.warn?.(
              'popup',
              'keyword-refresh-failed',
              globalThis.CCSLogger?.createRequestId?.('popup-keyword') || '',
              error?.message || String(error)
            );
          });
        });
      } catch (error) {
        console.warn('[触触搜] 关键字加载失败:', error);
      }
    })();
    return this._keywordLoadPromise;
  }

  // handleClick / executePinnedCover 兜底用：storage 没缓存（如刚开新 tab 还没
  // 选词或 SW 死过 cache 丢失）时，用户点击之后才发消息唤醒 SW 拿关键字。
  // 这条路径用户已经看到 popup 了，等 200-1500ms 拿关键字没有"打不开"的卡感。
  async _ensureKeywordOrFetch() {
    if (this.keyword.raw || this.keyword.text) return this.keyword;
    try {
      const fresh = await Promise.race([
        CCSKeywordClient.requestKeyword(CCSKeywordClient.INTENTS.POPUP_OPEN, {
          timeoutMs: 1200,
          retries: 0
        }),
        new Promise((resolve) => setTimeout(() => resolve(null), 1500))
      ]);
      if (fresh?.text) this.applyKeyword(fresh);
    } catch (_) { /* ignore */ }
    return this.keyword;
  }

  applyKeyword(keyword) {
    this.keyword = {
      text: keyword?.text || '',
      raw: keyword?.raw || keyword?.text || ''
    };
    this._renderKeyword();
  }

  async sendRuntimeAction(message, options = {}) {
    const client = globalThis.CCSRuntimeClient;
    if (client?.sendRuntimeMessage) {
      return client.sendRuntimeMessage(message, {
        timeoutMs: options.timeoutMs || 4000,
        retries: options.retries ?? 1
      });
    }
    const startedAt = Date.now();
    try {
      const data = await chrome.runtime.sendMessage(message);
      return { ok: true, data, elapsedMs: Date.now() - startedAt };
    } catch (error) {
      return {
        ok: false,
        error: { code: 'SEND_FAILED', message: error?.message || String(error) },
        elapsedMs: Date.now() - startedAt
      };
    }
  }

  runtimeErrorMessage(error) {
    const code = error?.code || '';
    if (code === 'TIMEOUT') return '后台启动较慢，请重试';
    if (code === 'SW_UNAVAILABLE') return '后台服务暂不可用，请重试';
    if (code === 'CONTENT_UNAVAILABLE') return '当前页面暂不支持直接操作，可刷新页面或使用剪贴板关键字';
    if (code === 'PERMISSION_DENIED') return '当前页面权限受限，无法执行该操作';
    return '操作失败，请重试';
  }

  // C 档重构后：popup.js 不再直接发消息拿关键字，统一过 CCSKeywordClient。
  // 老调用点（PromptLibraryManager / SettingsManager 等）若需要兜底刷新关键字，
  // 调用 this.refreshKeyword() 即可。
  async refreshKeyword(options = {}) {
    const fresh = await CCSKeywordClient.requestKeyword(CCSKeywordClient.INTENTS.POPUP_OPEN, {
      timeoutMs: options.timeoutMs || 1500,
      retries: options.retries ?? 1
    });
    if (fresh?.text || fresh?.raw) {
      this.keyword = fresh;
      this._renderKeyword();
    }
    return fresh;
  }

  // 关键字徽章渲染（与菜单 DOM 独立 —— 关键字变化不动菜单）
  _renderKeyword() {
    const keywordEl = document.getElementById('currentKeyword');
    if (!keywordEl) return;
    const keywordCopyEl = document.getElementById('currentKeywordCopy');
    const keywordWrapEl = keywordEl.closest('.menu-keyword-wrap');
    if (this.keyword?.text) {
      const displayText = this.formatKeyword(this.keyword.text);
      const fullKeyword = this.keyword.raw || this.keyword.text;
      keywordEl.textContent = `"${displayText}"`;
      if (keywordWrapEl) {
        keywordWrapEl.dataset.fullKeyword = fullKeyword;
        keywordWrapEl.classList.add('has-keyword');
      }
      keywordEl.removeAttribute('title');
      if (keywordCopyEl) {
        keywordCopyEl.hidden = false;
        keywordCopyEl.dataset.keyword = fullKeyword;
      }
    } else {
      keywordEl.textContent = '';
      if (keywordWrapEl) {
        keywordWrapEl.dataset.fullKeyword = '';
        keywordWrapEl.classList.remove('has-keyword');
      }
      keywordEl.removeAttribute('title');
      if (keywordCopyEl) {
        keywordCopyEl.hidden = true;
        keywordCopyEl.dataset.keyword = '';
      }
    }
  }

  formatKeyword(text) {
    if (!text) return '';
    const compact = text.replace(/\s+/g, ' ').trim();
    return compact.length > 15 ? compact.substring(0, 15) + '...' : compact;
  }

  // 子菜单展开/折叠（事件代理调用 —— 静态 HTML 里子菜单 DOM 已存在，只切 class）
  toggleSubmenu(parentEl, parentId) {
    const submenu = document.querySelector(`.submenu[data-parent-id="${parentId}"]`);
    if (!submenu) return;
    const willExpand = submenu.classList.contains('collapsed');
    submenu.classList.toggle('collapsed');
    parentEl.classList.toggle('expanded');
    if (willExpand) {
      // 展开后让 submenu 完整露出，避开 popup 底部 fixed .menu-footer（56px）。
      // 注：之前用 scrollIntoView + CSS scroll-padding-bottom，在部分 Chrome 版本上
      // 与 block:'nearest' 配合不可靠，最后一行仍被 footer 遮住。改成显式算偏移 + scrollBy，
      // 强制把 submenu 的底部抬到 footer 上方 12px 处。
      submenu.addEventListener('transitionend', () => {
        const FOOTER_H = 56;
        const BREATH = 12;          // submenu 底部与 footer 之间的呼吸距
        const SAFE_BOTTOM = FOOTER_H + BREATH;
        const rect = submenu.getBoundingClientRect();
        const viewportH = window.innerHeight || document.documentElement.clientHeight;
        const targetMaxBottom = viewportH - SAFE_BOTTOM;
        if (rect.bottom <= targetMaxBottom) return;     // 已经完整露出
        const delta = Math.ceil(rect.bottom - targetMaxBottom);
        // popup 用 body 自身做滚动容器（body { overflow-y: auto; max-height }）
        const scroller = document.scrollingElement || document.body;
        try {
          scroller.scrollBy({ top: delta, behavior: 'smooth' });
        } catch (_) {
          scroller.scrollTop += delta;   // 老浏览器无 options-form scrollBy 时降级
        }
      }, { once: true });
    }
  }

  // === Pinned cover quick-launch（与 sidepanel pin 共享 chrome.storage.local 状态） ===
  // 这些 storage key 必须与 sidepanel/sidepanel.js 顶部声明保持一致；那边是 SSoT，这里只读。
  static PIN_STORAGE_KEY = 'ccs_sidepanel_pinned_action';
  static CUSTOM_LINE_KEY = 'ccs_cover_custom_selected_line';
  static CUSTOM_PURPOSE_KEY = 'ccs_cover_custom_purpose';
  static RATIO_KEY = 'ccs_cover_aspect_ratio';
  static DEFAULT_PIN = { taskId: 'cover', categoryId: 'xiaohongshu' };
  static DEFAULT_RATIO = '5:2';

  async initPinnedCover() {
    try {
      const [storage, coverConfig] = await Promise.all([
        this.loadPinStorage(),
        this.loadCoverConfig()
      ]);
      if (!coverConfig || !Array.isArray(coverConfig.categories) || coverConfig.categories.length === 0) {
        return;   // 没有 cover 配置就不显示
      }
      let pin = storage.pin && storage.pin.taskId === 'cover' ? storage.pin : { ...PopupMenuRenderer.DEFAULT_PIN };
      const cat = coverConfig.categories.find((c) => c.id === pin.categoryId);
      if (!cat) {
        pin = { ...PopupMenuRenderer.DEFAULT_PIN };
      }
      // 自定义风格：必须有可用文本，否则退回默认（与 sidepanel 同逻辑）
      const customLine = (storage.customLine || '').trim();
      if (pin.categoryId === 'custom' && !customLine) {
        pin = { ...PopupMenuRenderer.DEFAULT_PIN };
      }
      this.pinnedCover = {
        pin,
        category: coverConfig.categories.find((c) => c.id === pin.categoryId),
        ratio: storage.ratio || PopupMenuRenderer.DEFAULT_RATIO,
        customLine
      };
      this.renderPinnedCover();
      this.bindPinnedCover();
    } catch (error) {
      console.warn('[触触搜] 置顶封面生成器加载失败:', error);
    }
  }

  loadPinStorage() {
    return new Promise((resolve) => {
      try {
        chrome.storage.local.get([
          PopupMenuRenderer.PIN_STORAGE_KEY,
          PopupMenuRenderer.CUSTOM_LINE_KEY,
          PopupMenuRenderer.CUSTOM_PURPOSE_KEY,
          PopupMenuRenderer.RATIO_KEY
        ], (result) => {
          resolve({
            pin: result?.[PopupMenuRenderer.PIN_STORAGE_KEY] || null,
            customLine: result?.[PopupMenuRenderer.CUSTOM_LINE_KEY] || result?.[PopupMenuRenderer.CUSTOM_PURPOSE_KEY]?.split(/\r?\n/)[0]?.trim() || '',
            ratio: typeof result?.[PopupMenuRenderer.RATIO_KEY] === 'string' ? result[PopupMenuRenderer.RATIO_KEY].trim() : ''
          });
        });
      } catch (_) {
        resolve({ pin: null, customLine: '', ratio: '' });
      }
    });
  }

  async loadCoverConfig() {
    try {
      const url = chrome.runtime.getURL('prompts/coverPrompts.json');
      const response = await fetch(url);
      if (!response.ok) return null;
      return await response.json();
    } catch (_) {
      return null;
    }
  }

  renderPinnedCover() {
    const section = document.getElementById('popupPin');
    const styleEl = document.getElementById('popupPinStyle');
    const ratioEl = document.getElementById('popupPinRatio');
    if (!section || !styleEl || !this.pinnedCover) return;
    const { category, ratio, customLine } = this.pinnedCover;
    if (!category) return;
    if (category.id === 'custom') {
      const preview = customLine.length > 15 ? customLine.slice(0, 15) + '…' : customLine;
      styleEl.textContent = preview ? `🖌️ ${preview}` : '🖌️ 自定义风格';
      styleEl.title = customLine || '';
    } else {
      styleEl.textContent = category.label || category.id;
      styleEl.title = '';
    }
    if (ratioEl) ratioEl.textContent = ratio || PopupMenuRenderer.DEFAULT_RATIO;
    section.hidden = false;
  }

  bindPinnedCover() {
    const actionBtn = document.getElementById('popupPinAction');
    if (!actionBtn) return;
    actionBtn.addEventListener('click', () => this.executePinnedCover());

    const hintBtn = document.getElementById('popupPinOpenSidepanel');
    if (hintBtn) {
      hintBtn.addEventListener('click', () => this.openSidePanel());
    }
  }

  async executePinnedCover() {
    if (!this.pinnedCover) return;
    const { category, customLine } = this.pinnedCover;
    if (!category) return;
    const engine = (category.engines || [])[0];
    if (!engine) {
      this.showToast('该风格暂无可用引擎');
      return;
    }
    let purpose = category.purpose || category.label;
    if (category.id === 'custom') {
      if (!customLine) {
        this.showToast('请到侧边栏 ✏️ 填写自定义风格');
        return;
      }
      purpose = customLine;
    }
    await this._ensureKeywordOrFetch();
    const keyword = this.keyword.raw || this.keyword.text;
    const menuItemId = `ccs-cover-${category.id}-${engine.id}`;
    try {
      const result = await this.sendRuntimeAction({
        action: 'executeMenuAction',
        menuItemId,
        menuType: 'cover',
        keyword,
        urlPattern: engine.urlPattern,
        engineId: engine.id,
        purpose,
        categoryId: category.id
      }, { timeoutMs: 5000, retries: 1 });
      if (!result.ok) {
        this.showToast(this.runtimeErrorMessage(result.error));
        return;
      }
      const response = result.data;
      if (response && response.success) {
        window.close();
      } else if (response && response.error === 'no-keyword') {
        this.showToast('没有选中文本或无法提取关键词');
      }
    } catch (error) {
      console.error('[触触搜] 置顶封面启动失败:', error);
      this.showToast('启动失败');
    }
  }

  async handleClick(item) {
    await this._ensureKeywordOrFetch();
    const keyword = this.keyword.raw || this.keyword.text;

    // 发送消息给 background 执行
    try {
      const result = await this.sendRuntimeAction({
        action: 'executeMenuAction',
        menuItemId: item.id,
        menuType: item.type,
        keyword: keyword,
        urlPattern: item.urlPattern,
        actionType: item.action,
        engineId: item.engineId,
        purpose: item.purpose  // 优化提示词需要 purpose 参数
      }, { timeoutMs: 5000, retries: 1 });
      if (!result.ok) {
        this.showToast(this.runtimeErrorMessage(result.error));
        return;
      }
      const response = result.data;

      if (response && response.success) {
        // 关闭 popup
        window.close();
      } else if (response && response.error === 'no-keyword') {
        this.showToast('没有选中文本或无法提取关键词');
      }
    } catch (error) {
      console.error('[触触搜] 菜单操作失败:', error);
      this.showToast('操作失败');
    }
  }

  itemFromElement(el) {
    if (!el) return null;
    return {
      id: el.dataset.menuId || '',
      type: el.dataset.menuType || '',
      urlPattern: el.dataset.urlPattern || '',
      action: el.dataset.action || '',
      engineId: el.dataset.engineId || '',
      purpose: el.dataset.purpose || ''
    };
  }

  bindEvents() {
    // 设置按钮点击
    const settingsToggle = document.getElementById('settingsToggle');
    settingsToggle.addEventListener('click', () => this.showSettings());

    // 返回菜单按钮
    const backToMenu = document.getElementById('backToMenu');
    backToMenu.addEventListener('click', () => this.showMenu());

    // 侧边栏切换（按当前状态显示「打开/关闭」相反操作）
    this.setupSidePanelButton();

    // 关键字复制按钮
    const keywordCopy = document.getElementById('currentKeywordCopy');
    if (keywordCopy) {
      keywordCopy.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.copyCurrentKeyword();
      });
    }

    const menuContainer = document.getElementById('menuContainer');
    if (menuContainer && !this._menuDelegationBound) {
      this._menuDelegationBound = true;
      menuContainer.addEventListener('click', (e) => {
        const itemEl = e.target?.closest?.('.menu-item[data-menu-id]');
        if (!itemEl || !menuContainer.contains(itemEl)) return;
        const item = this.itemFromElement(itemEl);
        if (!item?.id) return;
        // BUGFIX v1.6.23：has-children 项要展开子菜单，不是发 executeMenuAction。
        // v1.6.19 把菜单改静态 HTML 后忘了加这条分支——click delegation 让所有 menu-item
        // 都走 handleClick→sendMessage menuType='submenu'，SW 收到不知道怎么处理，结果
        // 子菜单永远不展开（"百问/速答/优化/封面 点了没反应"）。
        if (itemEl.classList.contains('has-children')) {
          this.toggleSubmenu(itemEl, item.id);
          return;
        }
        this.handleClick(item);
      });
    }
  }

  async copyCurrentKeyword() {
    const keyword = this.keyword.raw || this.keyword.text;
    if (!keyword) {
      this.showToast('没有可复制的关键字');
      return;
    }

    const btn = document.getElementById('currentKeywordCopy');
    try {
      await navigator.clipboard.writeText(keyword);
      if (btn) {
        const original = btn.textContent;
        btn.textContent = '✓';
        btn.classList.add('copied');
        btn.disabled = true;
        setTimeout(() => {
          btn.textContent = original;
          btn.classList.remove('copied');
          btn.disabled = false;
        }, 1200);
      }
    } catch (error) {
      console.error('[触触搜] 复制关键字失败:', error);
      this.showToast('复制失败');
    }
  }

  async setupSidePanelButton() {
    const btn = document.getElementById('openSidePanel');
    if (!btn) return;

    let isOpen = false;
    let windowId = null;
    const updateLabel = () => {
      btn.textContent = isOpen ? '📕 关闭侧边栏' : '📑 打开侧边栏';
    };

    try {
      const win = await chrome.windows.getCurrent();
      windowId = win.id;
      // v1.6.15 优先：读 background 持久化的 sidepanel 状态（即时）
      const cached = await new Promise((resolve) =>
        chrome.storage.local.get([`ccs_sp_open_${windowId}`], resolve));
      isOpen = !!cached?.[`ccs_sp_open_${windowId}`];
    } catch (_) {
      isOpen = false;
    }
    updateLabel();

    // v1.6.19: SW 校正消息推迟 800ms。先让 popup 完成首屏渲染，再去唤醒
    // SW（商店生产环境 SW 冷启动 ~500ms-2s，跟首屏抢 CPU 是用户报的卡顿
    // 主因）。storage 值 99% 情况下就是对的，校正只在 SW 死过没来得及写
    // 时才有差异。用户点关闭/打开时也会重新拿一次状态做权威判断。
    if (typeof windowId === 'number') {
      const idleSchedule = (fn) => {
        const ric = globalThis.requestIdleCallback;
        if (typeof ric === 'function') ric(fn, { timeout: 1200 });
        else setTimeout(fn, 800);
      };
      idleSchedule(() => {
        this.sendRuntimeAction({ action: 'getSidePanelState', windowId }, {
          timeoutMs: 1200,
          retries: 0
        }).then((result) => {
          if (!result.ok) return;
          const resp = result.data;
          if (resp && !!resp.isOpen !== isOpen) {
            isOpen = !!resp.isOpen;
            updateLabel();
          }
        }).catch(() => {});
      });
    }

    btn.addEventListener('click', async () => {
      if (isOpen) {
        await this.closeSidePanel(windowId);
      } else {
        await this.openSidePanel();
      }
    });
  }

  async closeSidePanel(windowId) {
    try {
      await this.sendRuntimeAction({ action: 'closeSidePanel', windowId }, {
        timeoutMs: 1200,
        retries: 0
      });
      window.close();
    } catch (error) {
      console.error('[触触搜] Close side panel failed:', error);
      this.showToast('关闭侧边栏失败');
    }
  }

  async openSidePanel() {
    if (!chrome.sidePanel || !chrome.sidePanel.open) {
      this.showToast('当前浏览器不支持侧边栏');
      return;
    }

    try {
      // Keep this call directly in click flow to preserve user gesture.
      await chrome.sidePanel.open({
        windowId: chrome.windows.WINDOW_ID_CURRENT
      });
      window.close();
      return;
    } catch (windowError) {
      console.warn('[触触搜] Open side panel by window failed:', windowError);
    }

    try {
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
      if (!tab || !tab.id) {
        throw new Error('No active tab for side panel fallback');
      }

      if (chrome.sidePanel.setOptions) {
        await chrome.sidePanel.setOptions({
          tabId: tab.id,
          path: 'sidepanel/sidepanel.html',
          enabled: true
        });
      }

      await chrome.sidePanel.open({ tabId: tab.id });
      window.close();
    } catch (error) {
      console.error('[触触搜] Open side panel failed:', error);
      this.showToast('打开侧边栏失败，请重试');
    }
  }

  async showSettings() {
    this.currentMode = 'settings';
    document.getElementById('menuContainer').style.display = 'none';
    document.getElementById('settingsPanel').style.display = 'block';
    document.getElementById('settingsToggle').style.display = 'none';
    // Lazy 初始化设置面板（首次打开扩展不必跑这一坨）
    await this.ensureSettingsInit();
  }

  async ensureSettingsInit() {
    if (this._settingsInitDone) return;
    this._settingsInitDone = true;
    this.initSettings();
  }

  loadScript(src) {
    return new Promise((resolve, reject) => {
      const existing = document.querySelector(`script[data-ccs-lazy="${src}"]`);
      if (existing) { resolve(); return; }
      const s = document.createElement('script');
      s.src = src;
      s.dataset.ccsLazy = src;
      s.onload = () => resolve();
      s.onerror = (e) => reject(e);
      document.head.appendChild(s);
    });
  }

  async ensurePromptLibrary() {
    if (!this._promptLibraryLoadPromise) {
      this._promptLibraryLoadPromise = this.loadScript('modules/PromptLibraryManager.js')
        .then(() => {
          if (window.CCSPopup && window.CCSPopup.PromptLibraryManager && !this.promptLibraryManager) {
            this.promptLibraryManager = new window.CCSPopup.PromptLibraryManager({
              onToast: (msg) => this.showToast(msg)
            });
            this.promptLibraryManager.init();
          }
        })
        .catch((e) => {
          console.error('[触触搜] 加载提示词库模块失败:', e);
          this._promptLibraryLoadPromise = null;  // 允许重试
          this.showToast('提示词库加载失败');
        });
    }
    return this._promptLibraryLoadPromise;
  }

  showMenu() {
    this.currentMode = 'menu';
    document.getElementById('menuContainer').style.display = 'block';
    document.getElementById('settingsPanel').style.display = 'none';
    document.getElementById('settingsToggle').style.display = 'block';
    // 隐藏所有子面板
    document.getElementById('blacklistSection').style.display = 'none';
    document.getElementById('shortcutSection').style.display = 'none';
    document.getElementById('debugSection').style.display = 'none';
    const promptLibrarySection = document.getElementById('promptLibrarySection');
    if (promptLibrarySection) promptLibrarySection.style.display = 'none';
  }

  showError(message) {
    const container = document.getElementById('menuContainer');
    container.innerHTML = `<div class="menu-error">${message}</div>`;
  }

  showToast(message) {
    const toast = document.createElement('div');
    toast.className = 'popup-toast';
    toast.textContent = message;
    document.body.appendChild(toast);

    setTimeout(() => {
      toast.classList.add('fade-out');
      setTimeout(() => toast.remove(), 300);
    }, 2000);
  }

  // ==================== 设置功能（保留自原有代码） ====================

  initSettings() {
    // 合并多次 storage.get 为一次（原 5 次串行回调改为 1 次）
    chrome.storage.local.get(['enabled', 'ccs_debug', 'ccs_voice_enabled'], (result) => {
      const enabled = result.enabled !== false;
      this.updateToggleButton(enabled);
      this.setDebugButtonState(!!result.ccs_debug);
      this.setVoiceButtonState(!!result.ccs_voice_enabled);
    });

    // 绑定设置按钮事件
    document.querySelectorAll('.setting-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const action = e.currentTarget.dataset.action;
        this.handleSettingAction(action);
      });
    });

    // 初始化黑名单
    this.loadBlacklist();

    // 初始化快捷键设置
    this.initShortcutSettings();

    // 提示词库改为 lazy：用户点 "📚 提示词库" 时才加载 PromptLibraryManager.js
  }

  handleSettingAction(action) {
    switch (action) {
      case 'toggle':
        this.toggleExtension();
        break;
      case 'blacklist':
        this.toggleBlacklistSection();
        break;
      case 'debug':
        this.toggleDebug();
        break;
      case 'voice':
        this.toggleVoice();
        break;
      case 'export-menu-state':
        this.exportMenuState();
        break;
      case 'diagnose':
        this.copyDiagnosticReport();
        break;
      case 'shortcut-settings':
        this.toggleShortcutSettings();
        break;
      case 'prompt-library':
        this.togglePromptLibrarySection();
        break;
      case 'open-welcome':
        chrome.tabs.create({ url: chrome.runtime.getURL('welcome/welcome.html') });
        window.close();
        break;
    }
  }

  toggleExtension() {
    chrome.storage.local.get(['enabled'], (result) => {
      const currentState = result.enabled !== false;
      const newState = !currentState;

      chrome.storage.local.set({ enabled: newState }, () => {
        this.updateToggleButton(newState);
        this.showToast(newState ? '插件已启用' : '插件已禁用');

        // 通知content script状态改变
        chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
          if (tabs[0]) {
            chrome.tabs.sendMessage(tabs[0].id, {
              action: 'toggleExtension',
              enabled: newState
            }).catch(() => {});
          }
        });
      });
    });
  }

  updateToggleButton(enabled) {
    const toggleBtn = document.querySelector('[data-action="toggle"]');
    if (toggleBtn) {
      const icon = toggleBtn.querySelector('.setting-icon');
      const label = toggleBtn.querySelector('.setting-label');

      if (enabled) {
        icon.textContent = '⚡';
        label.textContent = '点击禁用';
        toggleBtn.style.background = '#e8f5e9';
        toggleBtn.style.borderColor = '#4caf50';
      } else {
        icon.textContent = '⭕';
        label.textContent = '点击启用';
        toggleBtn.style.background = '#ffebee';
        toggleBtn.style.borderColor = '#f44336';
      }
    }
  }

  setDebugButtonState(enabled) {
    const btn = document.querySelector('[data-action="debug"]');
    if (!btn) return;
    const label = btn.querySelector('.setting-label');
    const icon = btn.querySelector('.setting-icon');

    if (enabled) {
      icon.textContent = '🐞';
      label.textContent = '调试日志：开';
      btn.style.background = '#fff8e1';
      btn.style.borderColor = '#fbc02d';
    } else {
      icon.textContent = '🐞';
      label.textContent = '调试日志：关';
      btn.style.background = '';
      btn.style.borderColor = '';
    }
  }

  toggleDebug() {
    chrome.storage.local.get(['ccs_debug'], (res) => {
      const current = !!res.ccs_debug;
      const next = !current;
      chrome.storage.local.set({ ccs_debug: next }, () => {
        this.setDebugButtonState(next);
        chrome.runtime.sendMessage({ action: 'updateDebug', enabled: next }).catch(() => {});
        chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
          if (tabs[0]) {
            chrome.tabs.sendMessage(tabs[0].id, { action: 'updateDebug', enabled: next }).catch(() => {});
          }
        });
        this.showToast(next ? '调试已开启' : '调试已关闭');
      });
    });
  }

  setVoiceButtonState(enabled) {
    const btn = document.querySelector('[data-action="voice"]');
    if (!btn) return;
    const label = btn.querySelector('.setting-label');
    const icon = btn.querySelector('.setting-icon');
    icon.textContent = '🎤';
    btn.title = '实验性功能：通过语音说出引擎名快速搜索（默认关）';
    // 主 label 只用 6 字保持与其它设置按钮等宽（与"调试日志：关"对齐），
    // "实验性"通过 .setting-badge 小角标表达，不挤压网格
    label.textContent = enabled ? '语音功能：开' : '语音功能：关';
    if (enabled) {
      btn.style.background = '#fff8e1';
      btn.style.borderColor = '#fbc02d';
    } else {
      btn.style.background = '';
      btn.style.borderColor = '';
    }
  }

  // 切换语音功能：开则 sidepanel 实例化语音模块、显示 🎤；关则全部不激活。
  // sidepanel 通过 storage onChanged 实时响应，无需重开。
  toggleVoice() {
    chrome.storage.local.get(['ccs_voice_enabled'], (res) => {
      const current = !!res.ccs_voice_enabled;
      const next = !current;
      chrome.storage.local.set({ ccs_voice_enabled: next }, () => {
        this.setVoiceButtonState(next);
        // 短文案与"调试已开启/关闭"等同类 toast 风格对齐，不再带括号注释
        this.showToast(next ? '语音功能已开启' : '语音功能已关闭');
      });
    });
  }

  toggleBlacklistSection() {
    const blacklistSection = document.getElementById('blacklistSection');
    const shortcutSection = document.getElementById('shortcutSection');
    const debugSection = document.getElementById('debugSection');
    const promptLibrarySection = document.getElementById('promptLibrarySection');

    if (blacklistSection.style.display === 'none') {
      blacklistSection.style.display = 'block';
      shortcutSection.style.display = 'none';
      debugSection.style.display = 'none';
      if (promptLibrarySection) promptLibrarySection.style.display = 'none';
      this.loadBlacklist();
    } else {
      blacklistSection.style.display = 'none';
    }
  }

  loadBlacklist() {
    chrome.storage.local.get(['ccs_settings'], (result) => {
      const settings = result.ccs_settings || { blacklist: [] };
      const blacklist = settings.blacklist || [];

      const countEl = document.querySelector('.blacklist-count');
      if (countEl) {
        countEl.textContent = blacklist.length;
      }

      const listEl = document.querySelector('.blacklist-list');
      if (listEl) {
        if (blacklist.length === 0) {
          listEl.innerHTML = '<div class="blacklist-empty">黑名单为空</div>';
        } else {
          listEl.innerHTML = blacklist.map(host => {
            const safe = this._escapeHtml(host);
            return `
            <div class="blacklist-item" data-host="${safe}">
              <span class="blacklist-host">${safe}</span>
              <button class="blacklist-remove" data-host="${safe}">移除</button>
            </div>
          `;
          }).join('');

          listEl.querySelectorAll('.blacklist-remove').forEach(btn => {
            btn.addEventListener('click', (e) => {
              const host = e.target.dataset.host;
              this.removeFromBlacklist(host);
            });
          });
        }
      }

      const clearBtn = document.querySelector('.clear-blacklist');
      if (clearBtn) {
        clearBtn.onclick = () => this.clearAllBlacklist();
      }
    });
  }

  /**
   * HTML 转义。blacklist host 来自 chrome.storage，渲染前必须过这层
   * （与 PromptLibraryManager._escapeHtml / SettingsManager._escapeHtml 同实现）。
   */
  _escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text == null ? '' : String(text);
    return div.innerHTML;
  }

  removeFromBlacklist(host) {
    chrome.storage.local.get(['ccs_settings'], (result) => {
      const settings = result.ccs_settings || { blacklist: [] };
      const index = settings.blacklist.indexOf(host);

      if (index > -1) {
        settings.blacklist.splice(index, 1);
        chrome.storage.local.set({ ccs_settings: settings }, () => {
          this.showToast(`已移除: ${host}`);
          this.loadBlacklist();

          chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
            if (tabs[0]) {
              chrome.tabs.sendMessage(tabs[0].id, {
                action: 'updateBlacklist',
                blacklist: settings.blacklist
              }).catch(() => {});
            }
          });
        });
      }
    });
  }

  clearAllBlacklist() {
    if (confirm('确定要清空所有黑名单吗？')) {
      chrome.storage.local.get(['ccs_settings'], (result) => {
        const settings = result.ccs_settings || {};
        settings.blacklist = [];

        chrome.storage.local.set({ ccs_settings: settings }, () => {
          this.showToast('黑名单已清空');
          this.loadBlacklist();

          chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
            if (tabs[0]) {
              chrome.tabs.sendMessage(tabs[0].id, {
                action: 'updateBlacklist',
                blacklist: []
              }).catch(() => {});
            }
          });
        });
      });
    }
  }

  initShortcutSettings() {
    chrome.storage.local.get(['ccs_settings'], (result) => {
      const settings = result.ccs_settings || {};
      const shortcutKey = settings.shortcutKey || 'Alt+S';

      const select = document.querySelector('.shortcut-key-select');
      if (select) {
        select.value = shortcutKey;
      }
    });

    const saveBtn = document.querySelector('.save-shortcut');
    if (saveBtn) {
      saveBtn.addEventListener('click', () => this.saveShortcutSettings());
    }
  }

  toggleShortcutSettings() {
    const shortcutSection = document.getElementById('shortcutSection');
    const blacklistSection = document.getElementById('blacklistSection');
    const debugSection = document.getElementById('debugSection');
    const promptLibrarySection = document.getElementById('promptLibrarySection');

    if (shortcutSection.style.display === 'none') {
      shortcutSection.style.display = 'block';
      blacklistSection.style.display = 'none';
      debugSection.style.display = 'none';
      if (promptLibrarySection) promptLibrarySection.style.display = 'none';
    } else {
      shortcutSection.style.display = 'none';
    }
  }

  async togglePromptLibrarySection() {
    const promptLibrarySection = document.getElementById('promptLibrarySection');
    const shortcutSection = document.getElementById('shortcutSection');
    const blacklistSection = document.getElementById('blacklistSection');
    const debugSection = document.getElementById('debugSection');

    if (!promptLibrarySection) return;

    if (promptLibrarySection.style.display === 'none') {
      promptLibrarySection.style.display = 'block';
      shortcutSection.style.display = 'none';
      blacklistSection.style.display = 'none';
      debugSection.style.display = 'none';
      // 首次打开提示词库时 lazy 加载 PromptLibraryManager.js
      await this.ensurePromptLibrary();
      if (this.promptLibraryManager) {
        this.promptLibraryManager.renderList();
      }
    } else {
      promptLibrarySection.style.display = 'none';
    }
  }

  saveShortcutSettings() {
    const select = document.querySelector('.shortcut-key-select');
    if (!select) return;

    const newShortcut = select.value;

    chrome.storage.local.get(['ccs_settings'], (result) => {
      const settings = result.ccs_settings || {};
      settings.shortcutKey = newShortcut;

      chrome.storage.local.set({ ccs_settings: settings }, () => {
        this.showToast('快捷键已更新为: ' + newShortcut);

        chrome.tabs.query({}, (tabs) => {
          tabs.forEach(tab => {
            chrome.tabs.sendMessage(tab.id, {
              action: 'updateShortcut',
              shortcutKey: newShortcut
            }).catch(() => {});
          });
        });
      });
    });
  }

  // v1.6.22 一键诊断：把顶部录像 IIFE 攒下的所有信号 + 实时探测
  // (WebGL renderer / SW ping / storage 白名单) 格式化成 Markdown 复制到剪贴板。
  async copyDiagnosticReport() {
    const btn = document.querySelector('[data-action="diagnose"]');
    const label = btn?.querySelector('.setting-label');
    const originalLabel = label?.textContent || '一键诊断';
    if (btn) {
      btn.disabled = true;
      if (label) label.textContent = '收集中...';
    }
    try {
      const report = await this._collectDiagnostics();
      await navigator.clipboard.writeText(report);
      const kb = (report.length / 1024).toFixed(1);
      if (label) label.textContent = `✓ 已复制 ${kb}KB`;
      this.showToast(`诊断信息已复制（${kb}KB），粘贴给开发者即可`);
    } catch (err) {
      console.error('[触触搜] 诊断收集失败:', err);
      this.showToast('诊断复制失败：' + (err?.message || String(err)));
      if (label) label.textContent = '❌ 失败';
    } finally {
      setTimeout(() => {
        if (btn) btn.disabled = false;
        if (label) label.textContent = originalLabel;
      }, 2000);
    }
  }

  async _collectDiagnostics() {
    const buffer = globalThis.__CCS_DIAG_BUFFER__ || { longTasks: [], errors: [], swPings: [] };
    const now = performance.now();
    const wallNow = Date.now();

    // 1. SW round-trip ping —— 测 SW 冷启状态
    let swPing = null;
    try {
      const sentAt = Date.now();
      const sentPerf = performance.now();
      const result = await Promise.race([
        chrome.runtime.sendMessage({ action: 'ccsDiagPing' }),
        new Promise((resolve) => setTimeout(() => resolve({ __timeout: true }), 3000))
      ]);
      const rtt = performance.now() - sentPerf;
      if (result?.__timeout) {
        swPing = { error: 'SW 3 秒内无响应（冷启严重 / 挂掉）', rttMs: '>3000' };
      } else if (result?.ok) {
        swPing = {
          rttMs: rtt.toFixed(1),
          swVersion: result.swVersion,
          clockSkewMs: result.swNow - sentAt - rtt / 2  // 粗略：SW 与 popup 的时间差（应 ~0）
        };
      } else {
        swPing = { error: 'SW 响应异常', raw: JSON.stringify(result).slice(0, 200) };
      }
    } catch (e) {
      swPing = { error: e?.message || String(e) };
    }

    // 2. WebGL renderer —— 一行判 HW 加速
    let webgl = null;
    try {
      const canvas = document.createElement('canvas');
      const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
      if (gl) {
        const ext = gl.getExtension('WEBGL_debug_renderer_info');
        if (ext) {
          webgl = {
            vendor: gl.getParameter(ext.UNMASKED_VENDOR_WEBGL),
            renderer: gl.getParameter(ext.UNMASKED_RENDERER_WEBGL)
          };
        } else {
          webgl = {
            vendor: gl.getParameter(gl.VENDOR),
            renderer: gl.getParameter(gl.RENDERER),
            note: 'WEBGL_debug_renderer_info 扩展不可用，上述是 masked 版本'
          };
        }
      } else {
        webgl = { error: 'WebGL 上下文创建失败（可能 GPU 进程崩溃 / 完全禁用）' };
      }
    } catch (e) {
      webgl = { error: e?.message || String(e) };
    }

    // 3. 当前 storage 状态（白名单，避免泄漏敏感）
    let storageState = null;
    try {
      storageState = await new Promise((resolve) => {
        chrome.storage.local.get([
          'enabled', 'ccs_debug', 'ccs_voice_enabled',
          'ccs_sidepanel_pinned_action', 'ccs_cover_aspect_ratio',
          'ccs_cover_custom_selected_line'
        ], (r) => resolve(r || {}));
      });
    } catch (e) {
      storageState = { error: e?.message || String(e) };
    }

    // 4. 当前活动 tab（去除 query string + hash 避免泄漏）
    let activeTab = null;
    try {
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
      if (tab) {
        let cleanUrl = tab.url || '';
        try {
          const u = new URL(cleanUrl);
          cleanUrl = `${u.protocol}//${u.host}${u.pathname}`;
        } catch (_) { /* keep raw */ }
        activeTab = { id: tab.id, url: cleanUrl, title: (tab.title || '').slice(0, 80) };
      }
    } catch (e) {
      activeTab = { error: e?.message || String(e) };
    }

    // 5. performance 时间线（mark + measure + navigation + resource + paint）
    const perfMarks = performance.getEntriesByType('mark').map((m) => ({
      name: m.name, startTime: m.startTime.toFixed(1)
    }));
    const perfMeasures = performance.getEntriesByType('measure').map((m) => ({
      name: m.name, startTime: m.startTime.toFixed(1), duration: m.duration.toFixed(1)
    }));
    const navEntry = performance.getEntriesByType('navigation')[0];
    // 完整 navigation timing —— v1.6.24 加：原来只有 4 个字段，加上 responseStart /
    // requestStart / fetchStart / domLoading / domComplete 等，能看清"从导航到 DCL"
    // 到底在哪个阶段卡住。
    const navInfo = navEntry ? {
      fetchStart: navEntry.fetchStart?.toFixed(1),
      requestStart: navEntry.requestStart?.toFixed(1),
      responseStart: navEntry.responseStart?.toFixed(1),
      responseEnd: navEntry.responseEnd?.toFixed(1),
      domInteractive: navEntry.domInteractive?.toFixed(1),
      domContentLoaded: navEntry.domContentLoadedEventEnd?.toFixed(1),
      domComplete: navEntry.domComplete?.toFixed(1),
      loadEventEnd: navEntry.loadEventEnd?.toFixed(1),
      transferSize: navEntry.transferSize,
      decodedBodySize: navEntry.decodedBodySize
    } : null;

    // 资源加载时间（关键新维度）—— 显示每个 <script> 和 <link> 的精确加载时长。
    // 如果某个 .js 文件 duration 几秒，凶手就是这个文件的读取/解析卡住了。
    const resources = performance.getEntriesByType('resource').map((r) => ({
      name: r.name.replace(chrome.runtime.getURL(''), '') || r.name,
      type: r.initiatorType,
      startTime: r.startTime.toFixed(1),
      duration: r.duration.toFixed(1),
      // responseStart - requestStart = 文件系统读取到第一字节耗时
      fileReadMs: (r.responseStart - r.requestStart).toFixed(1),
      transferSize: r.transferSize,
      decodedBodySize: r.decodedBodySize
    }));

    // Live fetch test —— 当前实测：读 3 个不同类型 / 大小的扩展文件，看延迟。
    // 这跟 popup.js / shared/*.js 的原始加载是平行对照实验：
    // - 如果原始加载 2s 但 fetch 0.5ms → Chrome 的 script loader 路径上有专门的卡顿
    //   （AV inline scan / V8 cold compile / extension code cache 失效等）
    // - 如果 fetch 也 2s → 全局文件 I/O 都慢（磁盘 / OneDrive / AV 通用扫描）
    const fetchTests = await Promise.all([
      'manifest.json',
      'popup/popup.boot.js',
      'popup/popup.bundle.js',
      'popup/popup.js',
      'popup/popup.css',
      'icons/16x16.png'
    ].map(async (rel) => {
      try {
        const url = chrome.runtime.getURL(rel);
        const t0 = performance.now();
        const resp = await fetch(url);
        const headersOk = resp.ok;
        const bytes = await resp.arrayBuffer();
        const ms = performance.now() - t0;
        return { file: rel, ms: ms.toFixed(1), bytes: bytes.byteLength, ok: headersOk };
      } catch (e) {
        return { file: rel, error: e?.message || String(e) };
      }
    }));

    // Performance memory（Chrome-only，但都跑 Chrome 所以一定有）
    let memInfo = null;
    try {
      if (performance.memory) {
        memInfo = {
          usedJSHeapSizeMB: (performance.memory.usedJSHeapSize / 1024 / 1024).toFixed(1),
          totalJSHeapSizeMB: (performance.memory.totalJSHeapSize / 1024 / 1024).toFixed(1),
          jsHeapSizeLimitMB: (performance.memory.jsHeapSizeLimit / 1024 / 1024).toFixed(0)
        };
      }
    } catch (_) { /* ignore */ }

    // 6. UA + 设备信息
    const manifest = chrome.runtime.getManifest();
    const ua = navigator.userAgent;
    const chromeMatch = ua.match(/Chrome\/([\d.]+)/);
    const env = {
      extVersion: manifest.version,
      extName: manifest.name,
      chromeVersion: chromeMatch ? chromeMatch[1] : '未知',
      ua,
      platform: navigator.platform,
      deviceMemory: navigator.deviceMemory != null ? `${navigator.deviceMemory} GB` : 'N/A',
      hardwareConcurrency: navigator.hardwareConcurrency || 'N/A',
      connection: navigator.connection ? {
        effectiveType: navigator.connection.effectiveType,
        downlink: navigator.connection.downlink,
        rtt: navigator.connection.rtt,
        saveData: navigator.connection.saveData
      } : null,
      screen: `${screen.width}×${screen.height}`,
      viewport: `${window.innerWidth}×${window.innerHeight}`,
      language: navigator.language,
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      cookieEnabled: navigator.cookieEnabled
    };

    // 7. 格式化成 Markdown
    const lines = [];
    const fence = '```';
    lines.push(`# 触触搜诊断报告`);
    lines.push(``);
    lines.push(`生成时间: ${new Date(wallNow).toISOString()}`);
    lines.push(`popup 录像时长: ${(now - (buffer.scriptStartPerf || 0)).toFixed(1)}ms (从 popup.js 顶层执行到点诊断按钮)`);
    lines.push(``);

    lines.push(`## 1. 环境`);
    lines.push(fence + 'json');
    lines.push(JSON.stringify(env, null, 2));
    lines.push(fence);
    lines.push(``);

    lines.push(`## 2. GPU / 硬件加速`);
    lines.push(fence + 'json');
    lines.push(JSON.stringify(webgl, null, 2));
    lines.push(fence);
    if (webgl?.renderer) {
      const r = webgl.renderer.toLowerCase();
      if (r.includes('swiftshader') || r.includes('software') || r.includes('llvmpipe')) {
        lines.push(`> ⚠️ 检测到软件渲染（${webgl.renderer}）—— HW 加速 OFF`);
      } else {
        lines.push(`> ✓ 看起来是真 GPU（${webgl.renderer}）`);
      }
    }
    lines.push(``);

    lines.push(`## 3. SW 连通性 / round-trip`);
    lines.push(fence + 'json');
    lines.push(JSON.stringify(swPing, null, 2));
    lines.push(fence);
    if (swPing?.rttMs && !isNaN(parseFloat(swPing.rttMs))) {
      const rttN = parseFloat(swPing.rttMs);
      if (rttN > 500) lines.push(`> ⚠️ SW round-trip ${rttN}ms（可能冷启动 / SW 卡）`);
      else if (rttN > 100) lines.push(`> 🟡 SW round-trip ${rttN}ms（偏高但能接受）`);
      else lines.push(`> ✓ SW round-trip ${rttN}ms`);
    }
    lines.push(``);

    lines.push(`## 4. Performance 时间线`);
    lines.push(`### 4.1 navigation timing`);
    lines.push(fence + 'json');
    lines.push(JSON.stringify(navInfo, null, 2));
    lines.push(fence);
    lines.push(``);
    lines.push(`### 4.2 performance.mark (${perfMarks.length})`);
    lines.push(fence);
    perfMarks.forEach((m) => lines.push(`${m.startTime.padStart(8)}ms  ${m.name}`));
    lines.push(fence);
    lines.push(``);
    lines.push(`### 4.3 performance.measure (${perfMeasures.length})`);
    lines.push(fence);
    perfMeasures.forEach((m) => lines.push(`${m.duration.padStart(8)}ms  ${m.name} (start ${m.startTime}ms)`));
    lines.push(fence);
    lines.push(``);

    // ⭐ 4.4 资源加载时间 —— 关键诊断维度
    // 显示每个 <script> / <link> 文件的精确加载耗时。
    // 如果某个文件 duration 几秒，那它就是卡顿元凶。
    lines.push(`### 4.4 资源加载时间 (${resources.length})`);
    lines.push(`> 列：startTime → duration (fileReadMs=responseStart-requestStart=文件系统读时间)`);
    lines.push(fence);
    resources.forEach((r) => {
      const sz = r.decodedBodySize != null ? `${(r.decodedBodySize / 1024).toFixed(1)}KB` : '';
      const start = String(r.startTime).padStart(8);
      const dur = String(r.duration).padStart(7);
      const read = String(r.fileReadMs).padStart(7);
      lines.push(`+${start}ms  dur ${dur}ms  read ${read}ms  ${sz.padStart(7)}  [${r.type}] ${r.name}`);
    });
    lines.push(fence);
    if (resources.length > 0) {
      const slowest = resources.slice().sort((a, b) =>
        parseFloat(b.duration) - parseFloat(a.duration))[0];
      if (parseFloat(slowest.duration) > 200) {
        lines.push(`> ⚠️ 最慢资源：${slowest.name} 加载耗时 ${slowest.duration}ms（>200ms 已经异常）`);
      }
    }
    lines.push(``);

    // 4.5 Paint timing
    lines.push(`### 4.5 paint timing`);
    if (!buffer.paints || buffer.paints.length === 0) {
      lines.push(`> 无 paint 事件捕获（paint observer 还没触发或浏览器不支持）`);
    } else {
      lines.push(fence);
      buffer.paints.forEach((p) => lines.push(`${p.startTime.toFixed(1).padStart(8)}ms  ${p.name}`));
      lines.push(fence);
    }
    lines.push(``);

    // 4.6 document.readyState 时间线 + DCL / load 事件
    lines.push(`### 4.6 readyState + 事件时间线`);
    lines.push(fence);
    (buffer.readyStateTimeline || []).forEach((r) => {
      lines.push(`${r.perf.toFixed(1).padStart(8)}ms  readyState → ${r.state}`);
    });
    (buffer.eventTimeline || []).forEach((e) => {
      lines.push(`${e.perf.toFixed(1).padStart(8)}ms  event:  ${e.name}`);
    });
    lines.push(fence);
    lines.push(``);

    // ⭐ 4.7 Live fetch test —— 平行对照实验，判磁盘 / AV / 脚本 loader 谁慢
    lines.push(`### 4.7 实时 fetch 测试（点诊断时即时跑）`);
    lines.push(`> 同样的扩展文件用 fetch() 拉。对比 4.4 资源原始加载耗时：`);
    lines.push(`> - 4.4 慢 + 4.7 快 → Chrome script loader 路径有 AV inline scan / 编译 cache 失效`);
    lines.push(`> - 4.4 慢 + 4.7 慢 → 全局文件 I/O 慢（磁盘 / AV 通用 / OneDrive on-demand）`);
    lines.push(fence);
    fetchTests.forEach((t) => {
      if (t.error) {
        lines.push(`${t.file.padEnd(25)}  ERROR: ${t.error}`);
      } else {
        lines.push(`${t.file.padEnd(25)}  ${String(t.ms).padStart(8)}ms  ${(t.bytes / 1024).toFixed(1).padStart(7)}KB`);
      }
    });
    lines.push(fence);
    lines.push(``);

    // 4.8 内存
    if (memInfo) {
      lines.push(`### 4.8 JS heap`);
      lines.push(fence + 'json');
      lines.push(JSON.stringify(memInfo, null, 2));
      lines.push(fence);
      lines.push(``);
    }

    lines.push(`## 5. 主线程长任务 >50ms (${buffer.longTasks.length})`);
    if (buffer.longTasks.length === 0) {
      lines.push(`> 无长任务捕获 —— 主线程在录像期间没有 >50ms 阻塞 ✓`);
    } else {
      lines.push(fence);
      buffer.longTasks.forEach((t) => {
        lines.push(`${t.duration.toFixed(1).padStart(7)}ms @ ${t.startTime.toFixed(1).padStart(7)}ms  ${t.name}`);
      });
      lines.push(fence);
    }
    lines.push(``);

    lines.push(`## 6. 控制台错误 / 警告 (${buffer.errors.length})`);
    if (buffer.errors.length === 0) {
      lines.push(`> 无错误捕获 ✓`);
    } else {
      lines.push(fence);
      buffer.errors.forEach((e) => {
        const t = (e.perf || 0).toFixed(0).padStart(6);
        lines.push(`[+${t}ms] ${e.level}: ${e.msg}`);
      });
      lines.push(fence);
    }
    lines.push(``);

    lines.push(`## 7. 扩展状态`);
    lines.push(`### 7.1 storage (白名单)`);
    lines.push(fence + 'json');
    lines.push(JSON.stringify(storageState, null, 2));
    lines.push(fence);
    lines.push(`### 7.2 active tab`);
    lines.push(fence + 'json');
    lines.push(JSON.stringify(activeTab, null, 2));
    lines.push(fence);
    lines.push(``);

    lines.push(`## 8. manifest 摘要`);
    lines.push(fence + 'json');
    lines.push(JSON.stringify({
      name: manifest.name,
      version: manifest.version,
      manifest_version: manifest.manifest_version,
      minimum_chrome_version: manifest.minimum_chrome_version,
      permissions: manifest.permissions,
      host_permissions: manifest.host_permissions
    }, null, 2));
    lines.push(fence);

    return lines.join('\n');
  }

  async exportMenuState() {
    const btn = document.querySelector('[data-action="export-menu-state"]');
    if (btn) {
      btn.disabled = true;
      const label = btn.querySelector('.setting-label');
      label.textContent = '获取中...';
    }

    try {
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
      const result = await this.sendRuntimeAction({
        action: 'getMenuDebugInfo',
        tabId: tab?.id
      }, { timeoutMs: 5000, retries: 0 });
      if (result.ok && result.data && result.data.success) {
        const trace = await globalThis.CCSLogger?.getTraceBuffer?.();
        this.showMenuDebugInfo({
          ...result.data.data,
          runtimeTrace: Array.isArray(trace) ? trace : []
        });
      } else {
        this.showToast('获取菜单状态失败');
      }
      if (btn) {
        btn.disabled = false;
        const label = btn.querySelector('.setting-label');
        label.textContent = '导出菜单状态';
      }
    } catch (error) {
      this.showToast('获取菜单状态失败');
      if (btn) {
        btn.disabled = false;
        const label = btn.querySelector('.setting-label');
        label.textContent = '导出菜单状态';
      }
    }
  }

  showMenuDebugInfo(data) {
    const debugSection = document.getElementById('debugSection');
    const textEl = document.querySelector('.menu-debug-text');
    const blacklistSection = document.getElementById('blacklistSection');
    const shortcutSection = document.getElementById('shortcutSection');
    const promptLibrarySection = document.getElementById('promptLibrarySection');

    if (!debugSection || !textEl) return;

    const formatted = JSON.stringify(data, null, 2);
    textEl.textContent = formatted;

    blacklistSection.style.display = 'none';
    shortcutSection.style.display = 'none';
    if (promptLibrarySection) promptLibrarySection.style.display = 'none';
    debugSection.style.display = 'block';

    navigator.clipboard.writeText(formatted).then(() => {
      this.showToast('菜单状态已复制到剪贴板');
    }).catch(() => {});

    const copyBtn = document.querySelector('.copy-debug-info');
    const closeBtn = document.querySelector('.close-debug-info');

    if (copyBtn) {
      copyBtn.onclick = () => {
        navigator.clipboard.writeText(formatted).then(() => {
          this.showToast('已复制到剪贴板');
        }).catch(() => {
          this.showToast('复制失败');
        });
      };
    }

    if (closeBtn) {
      closeBtn.onclick = () => {
        debugSection.style.display = 'none';
      };
    }
  }
}

// 初始化：bundle 以 async 加载时可能晚于 DOMContentLoaded，需要 readyState 兜底。
function bootPopupMenu() {
  // GUARD：本 bundle 也被 offscreen prewarm (offscreen/prewarm.js) 注入到预热文档里执行——
  // 预热文档没有 popup 的 DOM，init() 里 chrome.runtime.getManifest 在 offscreen Chrome 149 行为异常 +
  // 后续 bindEvents/showError 全部撞 null。检测到 menuContainer 不在就跳过 init，
  // 让 prewarm 只起"V8 cache / AV 扫描"预热作用，不再尝试初始化不存在的 UI。
  if (!document.getElementById('menuContainer')) return;
  const boot = globalThis.__CCS_POPUP_BOOT__;
  try { boot?.teardown?.(); } catch (_) { /* ignore */ }
  const renderer = new PopupMenuRenderer();
  Promise.resolve(renderer.init()).then(() => {
    const bootKeyword = boot?.getKeyword?.();
    if (bootKeyword?.text || bootKeyword?.raw) {
      renderer.applyKeyword(bootKeyword);
    }
    const intent = boot?.consumeIntent?.();
    if (intent === 'settings') {
      renderer.showSettings();
    } else if (intent === 'sidepanel') {
      renderer.openSidePanel();
    }
  }).catch((error) => {
    console.error('[触触搜] Popup 初始化失败:', error);
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', bootPopupMenu, { once: true });
} else {
  bootPopupMenu();
}
